compliant:
import { Effect } from "effect"

export interface PreviewInput {
  readonly customerId: string
  readonly subtotalCents: number
  readonly taxRate: number
  readonly currency: string
}

export interface InvoicePreview {
  readonly customerId: string
  readonly totalCents: number
  readonly currency: string
  readonly requiresPayment: boolean
}

const calculateTotal = (input: PreviewInput): Effect.Effect<number> =>
  Effect.sync(() => input.subtotalCents * (1 + input.taxRate))

export const buildPreview = (
  input: PreviewInput
): Effect.Effect<InvoicePreview> =>
  calculateTotal(input).pipe(
    Effect.map(Math.round),
    Effect.map((totalCents) => ({
      customerId: input.customerId,
      totalCents,
      currency: input.currency,
      requiresPayment: totalCents > 0
    }))
  )
